package app.veyra;
import android.content.Context;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class SearchAndDiscoveryTest {
 private Context c;@Before public void setup(){c=RuntimeEnvironment.getApplication();}
 private JSONObject title(String id,int year,double rating)throws Exception{return new JSONObject().put("id",id).put("vod_name",id).put("vod_year",year).put("vod_douban_score",rating).put("_provider","current").put("_kind","movie");}
 @Test public void filtersCombineMetadataWithoutChangingTitleIdentity()throws Exception{JSONObject matching=title("42",2024,8.2).put("vod_class","Action, Drama").put("vod_lang","English");SearchFilters.save(c,new SearchFilters.Criteria(2020,2025,8,"action","ENGLISH","movie"));List<JSONObject> result=SearchFilters.apply(c,Arrays.asList(matching,title("43",2010,9)));assertEquals(1,result.size());assertSame(matching,result.get(0));}
 @Test public void missingGenreAndLanguageDoNotPretendToMatch()throws Exception{SearchFilters.save(c,new SearchFilters.Criteria(0,0,0,"comedy","french","all"));assertTrue(SearchFilters.apply(c,Arrays.asList(title("42",2024,9))).isEmpty());}
 @Test public void filtersAreProfileSpecificAndClearable(){SearchFilters.save(c,new SearchFilters.Criteria(2020,0,7,"","","short"));assertTrue(SearchFilters.active(c));String other=ProfileStore.create(c,"Other");ProfileStore.select(c,other);assertFalse(SearchFilters.active(c));ProfileStore.select(c,"default");assertTrue(SearchFilters.active(c));SearchFilters.save(c,new SearchFilters.Criteria(0,0,0,"","","all"));assertFalse(SearchFilters.active(c));}
 @Test public void genrePreferenceAndWatchedFeedbackAffectRanking()throws Exception{ProfileStore.prefs(c,"discovery-prefs").edit().putString("genres","drama").commit();JSONObject drama=title("42",2024,8).put("vod_class","Drama"),comedy=title("43",2024,8).put("vod_class","Comedy");DiscoveryPreferences.Model model=new DiscoveryPreferences.Model(c);assertTrue(model.score(drama)>model.score(comedy));PersonalStore.watched(c,drama,true);assertTrue(new DiscoveryPreferences.Model(c).score(drama)<model.score(drama));}
 @Test public void negativeFeedbackCoversKnownEditionsButNotUnrelatedIds()throws Exception{JSONObject grouped=title("42",2024,8).put("_editions",new JSONArray().put(new JSONObject().put("provider","current").put("id","42")).put(new JSONObject().put("provider","classic").put("id","72")));PersonalStore.hide(c,grouped,true);assertTrue(PersonalStore.hidden(c,title("72",2024,8).put("_provider","classic")));assertFalse(PersonalStore.hidden(c,title("72",2024,8)));PersonalStore.hide(c,grouped,false);assertFalse(PersonalStore.hidden(c,grouped));}
}
